------------ import ------------
local UIModule = CS.Engine.UI.UIModule
------------ import ------------
local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
local ActionComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
local cs_coroutine = require 'XLua.cs_coroutine'
local CommonGoodsListNode = "Game.Behaviours.CommonGoodsList"

---@class UIActionConstructRewardNode           
local UIActionConstructRewardNode = Class("UIActionConstructRewardNode")
function UIActionConstructRewardNode:__init()
    self._data = nil
end

function UIActionConstructRewardNode:__delete()
    self._data = nil
end

function UIActionConstructRewardNode:Awake()
end

function UIActionConstructRewardNode:Start()
end

function UIActionConstructRewardNode:Refresh(levelId, ind)
    if not levelId then
        return
    end
    self._vo = ActionUtils.GetRegionLikabilityVo(levelId)
    if not self._vo then
        return
    end

    self._ind = ind
    self:FillSelf()
end

function UIActionConstructRewardNode:FillSelf()
    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._vo.regionId)
    CfUtils.FillText(self.TxtTitle, localize("升级到_num_级", {_num_ = self._vo.level}))
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsListNode)
    if scr then
        local vo = ActionUtils.GetRegionLikabilityVo(ActionUtils.GetRegionLikabilityId(self._vo.regionId, checkNumber(self._vo.level) - 1))
        local t = parse_rewards(vo.rewardGoods, vo.goodsNum)
        scr:FreshBaseUI(t, false, lv >= checkNumber(self._vo.level))
    end
    CfUtils.SetActive(self.FinishMask, lv >= checkNumber(self._vo.level))

    self._co = CfUtils.PlayDelayShowAnimate(self.controller.gameObject, self._ind, 0.05, 0, "Go")
end

function UIActionConstructRewardNode:OnDestroy()
    if self._co then 
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionConstructRewardNode